import{b as a,O as n,g as e,j as t}from"./chunks/framework.DcaUmd3X.js";const i="/assets/image-4.DXmn1zVC.webp",l="/assets/image-5.C0r00ejh.webp",g=JSON.parse('{"title":"第19章 · Redo 与 Undo","description":"","frontmatter":{},"headers":[],"relativePath":"database/oracle/under-the-hood/redo-undo/index.md","filePath":"数据库管理/Oracle从入门到精通/4.深入内核/第19章·Redo与Undo.md","lastUpdated":1783947942000}'),p={name:"database/oracle/under-the-hood/redo-undo/index.md"};function o(d,s,h,r,c,k){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="第19章-·-redo-与-undo" tabindex="-1">第19章 · Redo 与 Undo <a class="header-anchor" href="#第19章-·-redo-与-undo" aria-label="Permalink to &quot;第19章 · Redo 与 Undo&quot;">​</a></h1><h2 id="本章目标" tabindex="-1">本章目标 <a class="header-anchor" href="#本章目标" aria-label="Permalink to &quot;本章目标&quot;">​</a></h2><p>Redo 和 Undo 是 Oracle 最底层的两个日志机制。前面的 MVCC、事务、锁、崩溃恢复——全部建立在它们之上。这一章你会理解：</p><ol><li>Redo 和 Undo 分别记录什么——一个&quot;向前滚&quot;，一个&quot;向后退&quot;</li><li>Change Vector 是什么——Redo 的最小单位</li><li>Undo 段如何同时支持回滚、读一致性和事务恢复</li><li>块清除（Block Cleanout）是什么</li><li>ORA-01555 的深层原因——不只是 Undo 空间不够</li></ol><blockquote><p>如果说体系结构是 Oracle 的骨架，Redo 和 Undo 就是 Oracle 的血液系统。每一个操作都在两条血管中留下痕迹。</p></blockquote><h2 id="_19-1-redo-和-undo-是什么" tabindex="-1">19.1 Redo 和 Undo 是什么 <a class="header-anchor" href="#_19-1-redo-和-undo-是什么" aria-label="Permalink to &quot;19.1 Redo 和 Undo 是什么&quot;">​</a></h2><h3 id="_19-1-1-一句话区分" tabindex="-1">19.1.1 一句话区分 <a class="header-anchor" href="#_19-1-1-一句话区分" aria-label="Permalink to &quot;19.1.1 一句话区分&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Redo</th><th>Undo</th></tr></thead><tbody><tr><td><strong>作用</strong></td><td>重做——把已提交的变更&quot;重放&quot;一遍</td><td>撤销——把未提交的变更&quot;倒退&quot;回去</td></tr><tr><td><strong>记录什么</strong></td><td>&quot;怎么把数据变成新版本&quot;</td><td>&quot;怎么把数据变回旧版本&quot;</td></tr><tr><td><strong>保护什么</strong></td><td>已提交的数据（持久性）</td><td>未提交的数据（原子性+隔离性）</td></tr><tr><td><strong>存在哪里</strong></td><td>Redo Log Buffer → 联机重做日志 → 归档日志</td><td>Undo 表空间 → Undo 段</td></tr><tr><td><strong>什么时候写</strong></td><td>每次 DML 都写，在修改数据块<strong>之前</strong></td><td>每次 DML 都写，在修改数据块<strong>之前</strong></td></tr><tr><td><strong>什么时候读</strong></td><td>崩溃恢复</td><td>回滚 / 一致性读 / 事务恢复</td></tr></tbody></table><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 一条简单的 UPDATE：</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> students </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;张三丰&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> student_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2024001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Oracle 同时生成：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Redo：&quot;把 student_id=2024001 的 name 改成 &#39;张三丰&#39;&quot;（怎么重做）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Undo：&quot;把 student_id=2024001 的 name 改回 &#39;张三&#39;&quot;（怎么撤销）</span></span></code></pre></div><h3 id="_19-1-2-为什么两者都要" tabindex="-1">19.1.2 为什么两者都要 <a class="header-anchor" href="#_19-1-2-为什么两者都要" aria-label="Permalink to &quot;19.1.2 为什么两者都要&quot;">​</a></h3><p>有些数据库只有 Redo（没有 Undo），恢复时只能重放到最后——如果最后是未提交的事务，数据就不一致。有些只用 Undo——崩溃后已提交的数据可能丢失。</p><p>Oracle <strong>两者都要</strong>，因为它们各管各的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景1：事务进行到一半，用户 ROLLBACK</span></span>
<span class="line"><span>  → 只需要 Undo：&quot;逆向执行&quot;，撤销每一步</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景2：事务已提交，随后数据库崩溃</span></span>
<span class="line"><span>  → 只需要 Redo：&quot;重放&quot;所有已提交的变更</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景3：崩溃时既有已提交的、也有未提交的事务</span></span>
<span class="line"><span>  → 先用 Redo 把磁盘恢复到崩溃前一刻</span></span>
<span class="line"><span>  → 再用 Undo 回滚那些未提交的事务</span></span>
<span class="line"><span>  → 数据库恢复到一个一致的状态</span></span></code></pre></div><h2 id="_19-2-redo-深入" tabindex="-1">19.2 Redo 深入 <a class="header-anchor" href="#_19-2-redo-深入" aria-label="Permalink to &quot;19.2 Redo 深入&quot;">​</a></h2><h3 id="_19-2-1-change-vector——redo-的最小单位" tabindex="-1">19.2.1 Change Vector——Redo 的最小单位 <a class="header-anchor" href="#_19-2-1-change-vector——redo-的最小单位" aria-label="Permalink to &quot;19.2.1 Change Vector——Redo 的最小单位&quot;">​</a></h3><p>Redo 日志的最小组成单位是 <strong>Change Vector（变更向量）</strong>，一条 DML 可能产生多条 Change Vector。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> students </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;张三丰&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> student_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2024001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>产生的 Change Vector：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CV1: 修改数据块 X 的第 Y 行，把 name 从 &#39;张三&#39; 改为 &#39;张三丰&#39;</span></span>
<span class="line"><span>CV2: 修改 Undo 块 U 的第 V 行，写入 Undo 记录（旧值 &#39;张三&#39;）</span></span>
<span class="line"><span>CV3: 修改 Undo 段头的事务表，更新事务状态</span></span></code></pre></div><blockquote><p><strong>重要</strong>：Redo 不仅记录&quot;数据变更&quot;，也记录&quot;Undo 块的变更&quot;。这保证了即使 Undo 块本身损坏，也能通过 Redo 重建。</p></blockquote><h3 id="_19-2-2-redo-record——一组相关-change-vector-的集合" tabindex="-1">19.2.2 Redo Record——一组相关 Change Vector 的集合 <a class="header-anchor" href="#_19-2-2-redo-record——一组相关-change-vector-的集合" aria-label="Permalink to &quot;19.2.2 Redo Record——一组相关 Change Vector 的集合&quot;">​</a></h3><p>多个 Change Vector 被组织成一条 <strong>Redo Record</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Redo Record {</span></span>
<span class="line"><span>  SCN: 1001</span></span>
<span class="line"><span>  时间戳: 2024-09-01 10:30:00.001</span></span>
<span class="line"><span>  Change Vectors: [CV1, CV2, CV3]</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="_19-2-3-redo-从生成到归档的旅程" tabindex="-1">19.2.3 Redo 从生成到归档的旅程 <a class="header-anchor" href="#_19-2-3-redo-从生成到归档的旅程" aria-label="Permalink to &quot;19.2.3 Redo 从生成到归档的旅程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DML 执行</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Copy Redo 阶段：</span></span>
<span class="line"><span>  将变更前的数据（Old Value）拷贝到 Undo 块</span></span>
<span class="line"><span>  (这个 Undo 块的变化也产生 Redo CV)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Apply Change 阶段：</span></span>
<span class="line"><span>  将新值写入数据块（此时块变 Dirty）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Redo Records 写入 Redo Log Buffer（内存）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>LGWR 将 Redo Log Buffer 写入 Online Redo Log（磁盘）</span></span>
<span class="line"><span>  触发条件：COMMIT / 1/3满 / 3秒 / 1MB</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>ARCn 归档进程将写满的 Online Redo Log 复制到归档日志</span></span></code></pre></div><h3 id="_19-2-4-为什么要-先记日志再改数据-wal" tabindex="-1">19.2.4 为什么要&quot;先记日志再改数据&quot;（WAL） <a class="header-anchor" href="#_19-2-4-为什么要-先记日志再改数据-wal" aria-label="Permalink to &quot;19.2.4 为什么要&quot;先记日志再改数据&quot;（WAL）&quot;">​</a></h3><p>如果先改数据块、再记 Redo 日志：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先改数据：</span></span>
<span class="line"><span>  1. 改数据块 → 成功！</span></span>
<span class="line"><span>  2. 记日志... → 崩溃！日志没写成功</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结果：数据已经被改了，但没有 Redo 记录。</span></span>
<span class="line"><span>      如果此时 Undo 块也还没写到磁盘，崩溃恢复时无法判断这个变更是已提交还是未提交。</span></span></code></pre></div><p>Oracle 的做法（Write-Ahead Logging）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先记日志：</span></span>
<span class="line"><span>  1. 写 Change Vector 到 Redo Log Buffer（&quot;我准备要改这个块了&quot;）</span></span>
<span class="line"><span>  2. 改数据块</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结果：即使数据块在步骤2之后崩溃，Redo Log 中已经有步骤1的记录。</span></span>
<span class="line"><span>      恢复时根据 Redo 重放步骤2。</span></span></code></pre></div><p><strong>关键保证</strong>：在 DBWn 把脏块写入数据文件<strong>之前</strong>，Redo Log Buffer 中对应的 Change Vector 必须先被 LGWR 写入磁盘。这确保了磁盘上的数据永远不会比 Redo 日志&quot;更新&quot;。</p><h3 id="_19-2-5-redo-的大小与性能" tabindex="-1">19.2.5 Redo 的大小与性能 <a class="header-anchor" href="#_19-2-5-redo-的大小与性能" aria-label="Permalink to &quot;19.2.5 Redo 的大小与性能&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看 Redo 日志信息</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> group#, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sequence</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#, bytes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> size_mb, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">status</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> v$</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看 Redo 生成速率</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">value</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> v$sysstat</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;redo size&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;redo entries&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;redo writes&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Redo 日志太大 → 切换周期长 → 但崩溃恢复时需要扫描的日志也多 Redo 日志太小 → 切换频繁 → 日志切换是额外的 I/O 开销</p><h2 id="_19-3-undo-深入" tabindex="-1">19.3 Undo 深入 <a class="header-anchor" href="#_19-3-undo-深入" aria-label="Permalink to &quot;19.3 Undo 深入&quot;">​</a></h2><h3 id="_19-3-1-undo-的三个用途" tabindex="-1">19.3.1 Undo 的三个用途 <a class="header-anchor" href="#_19-3-1-undo-的三个用途" aria-label="Permalink to &quot;19.3.1 Undo 的三个用途&quot;">​</a></h3><p>Undo 段中的数据服务于三个目的：</p><p>Undo 的三大职能：</p><p><img src="`+i+`" alt="alt text"></p><blockquote><p>三种用途中，读一致性（MVCC）是最容易被低估的。很多人以为 Undo 只在 ROLLBACK 时用——实际上，<strong>每一条 SELECT 都可能用到 Undo</strong>，如果它查询的数据块在查询开始后被修改过。</p></blockquote><h3 id="_19-3-2-undo-段的结构" tabindex="-1">19.3.2 Undo 段的结构 <a class="header-anchor" href="#_19-3-2-undo-段的结构" aria-label="Permalink to &quot;19.3.2 Undo 段的结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Undo 段</span></span>
<span class="line"><span>  ├── 段头（Segment Header）</span></span>
<span class="line"><span>  │   ├── 事务表（Transaction Table）→ 记录所有使用这个 Undo 段的事务状态</span></span>
<span class="line"><span>  │   └── 空闲块列表</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └── Undo 块（Undo Blocks）</span></span>
<span class="line"><span>      └── Undo 记录链接成单链表</span></span>
<span class="line"><span>          记录1（最新）→ 记录2 → 记录3 → ...（最旧）</span></span></code></pre></div><p>每个事务在事务表中占一行，包含：</p><ul><li>事务 ID（XID）</li><li>事务状态（Active / Committed / Aborted）</li><li>Undo 记录链表的指针</li><li>提交 SCN（如果已提交）</li></ul><h3 id="_19-3-3-undo-记录的链接" tabindex="-1">19.3.3 Undo 记录的链接 <a class="header-anchor" href="#_19-3-3-undo-记录的链接" aria-label="Permalink to &quot;19.3.3 Undo 记录的链接&quot;">​</a></h3><p>一个事务可能修改很多行，产生多条 Undo 记录，它们被链接成单向链表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务 TX-001 的 Undo 链：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Undo 记录3（最新）  → Undo 记录2  → Undo 记录1（最旧）</span></span>
<span class="line"><span>&quot;把score改回85&quot;      &quot;把name改回张三&quot;  &quot;删除这行&quot;</span></span>
<span class="line"><span>    ↑                                      ↑</span></span>
<span class="line"><span>    └──────────── 指针方向 ─────────────────┘</span></span>
<span class="line"><span>    (每条记录指向更旧的记录)</span></span></code></pre></div><p>ROLLBACK 时，从最新记录开始，沿着链表逆向执行。对于 <code>SELECT</code> 的一致性读，Oracle 从最新版本开始，沿着 Undo 链往回找，直到找到目标 SCN 之前的版本。</p><h2 id="_19-4-块清除-block-cleanout" tabindex="-1">19.4 块清除（Block Cleanout） <a class="header-anchor" href="#_19-4-块清除-block-cleanout" aria-label="Permalink to &quot;19.4 块清除（Block Cleanout）&quot;">​</a></h2><h3 id="_19-4-1-什么情况需要块清除" tabindex="-1">19.4.1 什么情况需要块清除 <a class="header-anchor" href="#_19-4-1-什么情况需要块清除" aria-label="Permalink to &quot;19.4.1 什么情况需要块清除&quot;">​</a></h3><p>当事务提交时，数据块里的 ITL 条目被标记为&quot;已提交&quot;，但数据块本身不会马上写回磁盘。如果之后另一个事务读到了这个块，它需要确认：ITL 中标记为&quot;已提交&quot;的事务是何时提交的。</p><p>这个确认操作就是<strong>块清除</strong>——把事务的提交 SCN 写到 ITL 条目中。</p><h3 id="_19-4-2-两种清除方式" tabindex="-1">19.4.2 两种清除方式 <a class="header-anchor" href="#_19-4-2-两种清除方式" aria-label="Permalink to &quot;19.4.2 两种清除方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>代价</th></tr></thead><tbody><tr><td><strong>快速清除</strong></td><td>Undo 段头的事务表中仍有该事务的记录</td><td>读 Undo 段头，拿到提交 SCN，写入 ITL</td></tr><tr><td><strong>延迟清除</strong></td><td>Undo 段头的事务信息已经被覆盖</td><td>需要从 Undo 段头找到事务表，再从 ITL 找到 Undo 记录，逐步回溯</td></tr></tbody></table><p>如果延迟清除需要的 Undo 也已被覆盖，就会出现 <code>ORA-01555</code>。</p><h3 id="_19-4-3-为什么-commit-后第一次查询可能产生-redo" tabindex="-1">19.4.3 为什么 COMMIT 后第一次查询可能产生 Redo <a class="header-anchor" href="#_19-4-3-为什么-commit-后第一次查询可能产生-redo" aria-label="Permalink to &quot;19.4.3 为什么 COMMIT 后第一次查询可能产生 Redo&quot;">​</a></h3><p>块清除本身是一个对数据块的修改（写入提交 SCN），因此会产生 Redo！这就是为什么有时候一个纯 SELECT 操作，竟然会触发 Redo 写入——块清除在悄悄改写数据块。</p><h2 id="_19-5-redo-和-undo-的协作——一个完整的故事" tabindex="-1">19.5 Redo 和 Undo 的协作——一个完整的故事 <a class="header-anchor" href="#_19-5-redo-和-undo-的协作——一个完整的故事" aria-label="Permalink to &quot;19.5 Redo 和 Undo 的协作——一个完整的故事&quot;">​</a></h2><p>让我们追踪一条 UPDATE 从开始到提交的完整旅程，看 Redo 和 Undo 如何配合：</p><p>时间线：UPDATE students SET name = &#39;张三丰&#39; WHERE student_id = 2024001;</p><p><img src="`+l+`" alt="alt text"></p><p><strong>如果 Step 4 和 Step 5 之间崩溃</strong>：</p><ul><li>Redo 日志有 Step 4 的 Redo Record</li><li>重启后，Oracle 看到此事务的 Redo 但没有对应的 Commit 标记</li><li>使用 Undo 回滚此事务 → 数据回到修改前</li></ul><p><strong>如果 Step 5 之后崩溃（但 Step 6 之前）</strong>：</p><ul><li>Redo 日志有完整的 COMMIT 标记</li><li>重启后，Oracle 从 Redo 中重放 Step 2 和 Step 3</li><li>同时重放 Undo 块的变更</li><li>数据模块恢复到 Step 3 之后的状态 → 与 COMMIT 时一致</li></ul><h2 id="_19-6-ora-01555-再探——这次从-redo-undo-视角" tabindex="-1">19.6 ORA-01555 再探——这次从 Redo/Undo 视角 <a class="header-anchor" href="#_19-6-ora-01555-再探——这次从-redo-undo-视角" aria-label="Permalink to &quot;19.6 ORA-01555 再探——这次从 Redo/Undo 视角&quot;">​</a></h2><p>第17章从 MVCC 角度解释了 ORA-01555。现在从 Redo/Undo 的角度再深化：</p><h3 id="_19-6-1-ora-01555-发生的三个条件" tabindex="-1">19.6.1 ORA-01555 发生的三个条件 <a class="header-anchor" href="#_19-6-1-ora-01555-发生的三个条件" aria-label="Permalink to &quot;19.6.1 ORA-01555 发生的三个条件&quot;">​</a></h3><p>必须同时满足：</p><ol><li><strong>一个长时间运行的查询</strong>（比如持续 30 分钟的大报表）</li><li><strong>查询执行期间，它的数据被其他会话修改</strong>（新版本产生，旧版本进 Undo）</li><li><strong>这些 Undo 数据被覆盖了</strong>（UNDO_RETENTION 太短 / Undo 表空间太小）</li></ol><h3 id="_19-6-2-延迟块清除导致的-01555" tabindex="-1">19.6.2 延迟块清除导致的 01555 <a class="header-anchor" href="#_19-6-2-延迟块清除导致的-01555" aria-label="Permalink to &quot;19.6.2 延迟块清除导致的 01555&quot;">​</a></h3><p>即使没有长时间运行的查询，也可能遇到 ORA-01555：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个事务修改了大量数据并 COMMIT</span></span>
<span class="line"><span>  → ITL 中标记为已提交，但没有写入提交 SCN（需要清除）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>之后另一个查询扫描这个块</span></span>
<span class="line"><span>  → 需要做延迟块清除（知道事务的提交 SCN）</span></span>
<span class="line"><span>  → 去 Undo 段头查事务表</span></span>
<span class="line"><span>  → 但事务表的信息已被覆盖！</span></span>
<span class="line"><span>  → ORA-01555</span></span></code></pre></div><p>解决这类 ORA-01555，需要在批量 DML 后手动执行 COMMIT 不必做什么——实际上应该<strong>分批提交，并且每批提交后让 Oracle 有时间完成块清除</strong>。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心理解</th></tr></thead><tbody><tr><td>Redo 是什么</td><td>&quot;重做日志&quot;——记录怎么把数据变成新版本，保证持久性</td></tr><tr><td>Undo 是什么</td><td>&quot;撤销日志&quot;——记录怎么把数据变回旧版本，服务于回滚+读一致性+事务恢复</td></tr><tr><td>Change Vector</td><td>Redo 的最小单位，一次 DML 产生多条 CV</td></tr><tr><td>WAL 原则</td><td>在数据块写入磁盘前，对应的 Redo 必须先写入磁盘</td></tr><tr><td>Undo 三大用途</td><td>事务回滚、读一致性（MVCC）、事务恢复（SMON）</td></tr><tr><td>块清除</td><td>将提交 SCN 写入 ITL，清除操作本身也产生 Redo</td></tr><tr><td>ORA-01555（Redo/Undo视角）</td><td>Undo 被覆盖 → 一致性读失败或延迟块清除失败</td></tr></tbody></table><h2 id="自检清单" tabindex="-1">自检清单 <a class="header-anchor" href="#自检清单" aria-label="Permalink to &quot;自检清单&quot;">​</a></h2><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Redo 和 Undo 分别记录什么内容？各自服务于什么目的？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 为什么 Oracle 需要两者都用，而不是只用其中一种？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Change Vector、Redo Record、Redo Log File 的关系是什么？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> WAL 原则的核心是什么？为什么 DBWn 写数据块之前必须确保什么？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Undo 除了事务回滚之外还有什么用途？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 什么是块清除？为什么纯 SELECT 也可能产生 Redo？</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 从 Redo/Undo 角度，ORA-01555 如何发生？</li></ul><blockquote><p><strong>下一章预告</strong>：表与索引深度——第四篇最后一章。堆表、IOT、临时表的内部机制，B*Tree 索引的根枝叶结构，以及位图索引为什么不适合 OLTP。</p></blockquote>`,79)])])}const b=a(p,[["render",o]]);export{g as __pageData,b as default};
